inputs.expression:
inputs.email.email_headers[header_key="Authentication-Results"].(
    $val := header_value;
    $capitalize := function($str) { $str ? $uppercase($substring($str, 0, 1)) & $substring($str, 1) : null };

    $extRes := function($regex) { 
        $match($val, $regex) ? $capitalize($match($val, $regex)[0].groups[0]) : null 
    };
    $extRsn := function($regex) { 
        $match($val, $regex) ? $trim($match($val, $regex)[0].groups[0]) : null 
    };

    {
        "spf_result": $extRes(/spf=([^\s;]+)/i),
        "spf_reason": $extRsn(/spf=[^\s;]+\s*([\s\S]*?)(?:;\s*(?:dkim|dmarc)=|$)/i),
        "dkim_result": $extRes(/dkim=([^\s;]+)/i),
        "dkim_reason": $extRsn(/dkim=[^\s;]+\s*([\s\S]*?)(?:;\s*(?:spf|dmarc)=|$)/i),
        "dmarc_result": $extRes(/dmarc=([^\s;]+)/i),
        "dmarc_reason": $extRsn(/dmarc=[^\s;]+\s*([\s\S]*?)(?:;\s*(?:spf|dkim)=|$)/i)
    }
)
